import type { CSSProperties, HTMLAttributes } from "react";
import "./gradual-blur.css";

export type GradualBlurProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  /** Which edge of the container it sits on. */
  edge?: "top" | "bottom" | "left" | "right";
  /** How far in from the edge it reaches, as any CSS length. Defaults to --ds-space-3xl. */
  size?: string;
  /** subtle, normal or strong. Sets the blur of the outermost layer from the --ds-blur steps. */
  strength?: "subtle" | "normal" | "strong";
  /** How many layers, 2 to 8. Each one is a backdrop-filter, so fewer is cheaper. */
  layers?: number;
  /** Fade to the page colour on top of the blur. */
  fade?: boolean;
  /** "absolute" fills its positioned parent's edge, "sticky" sticks to the edge of the scroller it's in, "fixed" to the screen. */
  position?: "absolute" | "sticky" | "fixed";
  /** Keep it showing when the scroller is at that end. By default it fades away there. */
  always?: boolean;
};

/* Blurs whatever scrolls under it, more the closer it gets to the edge. Decorative, so it's hidden from
   screen readers and ignores the pointer. Don't give its parent overflow, opacity, a mask or a filter. */
export default function GradualBlur({
  edge = "bottom",
  size,
  strength = "normal",
  layers = 6,
  fade = false,
  position = "absolute",
  always = false,
  className,
  style,
  ...rest
}: GradualBlurProps) {
  const count = Math.min(8, Math.max(2, Math.round(layers)));
  const classes = [
    "ob-gradual-blur",
    `ob-gradual-blur--${edge}`,
    strength !== "normal" && `ob-gradual-blur--${strength}`,
    fade && "ob-gradual-blur--fade",
    position !== "absolute" && `ob-gradual-blur--${position}`,
    always && "ob-gradual-blur--always",
    className,
  ]
    .filter(Boolean)
    .join(" ");
  const sized = size ? ({ "--ob-gradual-blur-size": size, ...style } as CSSProperties) : style;
  return (
    <div {...rest} className={classes} style={sized} aria-hidden="true">
      {Array.from({ length: count }, (_, i) => (
        <span key={i} />
      ))}
    </div>
  );
}

/* ob-gradual-blur. An edge where content softens the closer it gets.
 *
 *   <div class="ob-gradual-blur ob-gradual-blur--bottom" aria-hidden="true">
 *     <span></span><span></span><span></span><span></span><span></span><span></span>
 *   </div>
 *
 * Put it inside a positioned container (or a scroller, with --sticky). Each
 * span is a layer with a stronger backdrop blur, masked to a band that starts
 * further in from the edge, so the blur builds up in steps too small to see.
 * 6 spans is the default. Any number from 2 to 8 works and the bands share
 * the height out between them. More than 8 are hidden, because every layer
 * is a backdrop-filter and they're expensive.
 *
 * Don't put overflow, opacity, a mask or a filter on the container. Any of
 * them stops the layers seeing what's behind. */

:where(:root) {
  --ob-gradual-blur-size: var(--ds-space-3xl);
  --ob-gradual-blur-strength: var(--ds-blur-md);
  --ob-gradual-blur-fade: 0;
}

.ob-gradual-blur {
  --ob-gb-n: 6;
  --ob-gb-dir: to bottom;
  position: absolute;
  z-index: var(--ds-z-raised);
  inset: auto 0 0 0;
  height: var(--ob-gradual-blur-size);
  pointer-events: none;
}
.ob-gradual-blur:has(> :nth-child(2):last-child) { --ob-gb-n: 2; }
.ob-gradual-blur:has(> :nth-child(3):last-child) { --ob-gb-n: 3; }
.ob-gradual-blur:has(> :nth-child(4):last-child) { --ob-gb-n: 4; }
.ob-gradual-blur:has(> :nth-child(5):last-child) { --ob-gb-n: 5; }
.ob-gradual-blur:has(> :nth-child(6):last-child) { --ob-gb-n: 6; }
.ob-gradual-blur:has(> :nth-child(7):last-child) { --ob-gb-n: 7; }
.ob-gradual-blur:has(> :nth-child(n+8)) { --ob-gb-n: 8; }

/* Which edge. The mask runs from the inside (clear) to the edge (blurred). */
.ob-gradual-blur--bottom { inset: auto 0 0 0; height: var(--ob-gradual-blur-size); width: auto; --ob-gb-dir: to bottom; }
.ob-gradual-blur--top { inset: 0 0 auto 0; height: var(--ob-gradual-blur-size); width: auto; --ob-gb-dir: to top; }
.ob-gradual-blur--left { inset: 0 auto 0 0; width: var(--ob-gradual-blur-size); height: auto; --ob-gb-dir: to left; }
.ob-gradual-blur--right { inset: 0 0 0 auto; width: var(--ob-gradual-blur-size); height: auto; --ob-gb-dir: to right; }

/* Fixed to the screen, or sticky at the edge of the scroller it's in. Sticky
   takes no room: it's pulled back over the content with a negative margin.
   Put a top one first in the scroller and a bottom one last. */
.ob-gradual-blur--fixed { position: fixed; }
.ob-gradual-blur--sticky.ob-gradual-blur--top,
.ob-gradual-blur--sticky.ob-gradual-blur--bottom { position: sticky; width: auto; }
.ob-gradual-blur--sticky.ob-gradual-blur--top { top: 0; bottom: auto; margin-bottom: calc(var(--ob-gradual-blur-size) * -1); }
.ob-gradual-blur--sticky.ob-gradual-blur--bottom { bottom: 0; top: auto; margin-top: calc(var(--ob-gradual-blur-size) * -1); }
.ob-gradual-blur--sticky.ob-gradual-blur--left,
.ob-gradual-blur--sticky.ob-gradual-blur--right { position: sticky; height: 100%; }
.ob-gradual-blur--sticky.ob-gradual-blur--left { left: 0; margin-right: calc(var(--ob-gradual-blur-size) * -1); }
.ob-gradual-blur--sticky.ob-gradual-blur--right { right: 0; margin-left: calc(var(--ob-gradual-blur-size) * -1); }

/* How hard it blurs. Strength is the blur of the outermost layer on its own. */
.ob-gradual-blur--subtle { --ob-gradual-blur-strength: var(--ds-blur-sm); }
.ob-gradual-blur--strong { --ob-gradual-blur-strength: var(--ds-blur-lg); }

/* A fade to the page colour on top of the blur. */
.ob-gradual-blur--fade { --ob-gradual-blur-fade: 0.85; }

.ob-gradual-blur > * {
  --ob-gb-from: calc((var(--i, 1) - 1) / var(--ob-gb-n) * 100%);
  --ob-gb-to: calc(var(--i, 1) / var(--ob-gb-n) * 100%);
  position: absolute;
  inset: 0;
  -webkit-backdrop-filter: blur(calc(var(--ob-gradual-blur-strength) * var(--i, 1) / var(--ob-gb-n)));
  backdrop-filter: blur(calc(var(--ob-gradual-blur-strength) * var(--i, 1) / var(--ob-gb-n)));
  -webkit-mask-image: linear-gradient(var(--ob-gb-dir), transparent var(--ob-gb-from), black var(--ob-gb-to));
  mask-image: linear-gradient(var(--ob-gb-dir), transparent var(--ob-gb-from), black var(--ob-gb-to));
}
.ob-gradual-blur > :nth-child(1) { --i: 1; }
.ob-gradual-blur > :nth-child(2) { --i: 2; }
.ob-gradual-blur > :nth-child(3) { --i: 3; }
.ob-gradual-blur > :nth-child(4) { --i: 4; }
.ob-gradual-blur > :nth-child(5) { --i: 5; }
.ob-gradual-blur > :nth-child(6) { --i: 6; }
.ob-gradual-blur > :nth-child(7) { --i: 7; }
.ob-gradual-blur > :nth-child(8) { --i: 8; }
.ob-gradual-blur > :nth-child(n+9) { display: none; }

.ob-gradual-blur::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: var(--ob-gradual-blur-fade);
  background: linear-gradient(var(--ob-gb-dir), color-mix(in srgb, var(--ds-color-bg) 0%, transparent), var(--ds-color-bg));
}

/* Gone when the scroller is at that end, so nothing is blurred that has
   nothing under it. It is the layers that fade, not the container, because
   an opacity on the container would stop them seeing the page. --always
   keeps it. Browsers without scroll-driven animations just keep it on. */
@keyframes ob-gradual-blur-in { from { opacity: 0; } to { opacity: 1; } }
@supports (animation-timeline: scroll()) {
  .ob-gradual-blur:not(.ob-gradual-blur--always) > *,
  .ob-gradual-blur:not(.ob-gradual-blur--always)::after {
    animation: ob-gradual-blur-in linear both;
    animation-timeline: scroll(nearest block);
    animation-range: 0 var(--ob-gradual-blur-size);
  }
  .ob-gradual-blur:not(.ob-gradual-blur--always)::after { animation-name: ob-gradual-blur-fade-in; }
  .ob-gradual-blur--bottom:not(.ob-gradual-blur--always) > *,
  .ob-gradual-blur--bottom:not(.ob-gradual-blur--always)::after {
    animation-direction: reverse;
    animation-range: calc(100% - var(--ob-gradual-blur-size)) 100%;
  }
  .ob-gradual-blur--left:not(.ob-gradual-blur--always) > *,
  .ob-gradual-blur--left:not(.ob-gradual-blur--always)::after,
  .ob-gradual-blur--right:not(.ob-gradual-blur--always) > *,
  .ob-gradual-blur--right:not(.ob-gradual-blur--always)::after { animation-timeline: scroll(nearest inline); }
  .ob-gradual-blur--right:not(.ob-gradual-blur--always) > *,
  .ob-gradual-blur--right:not(.ob-gradual-blur--always)::after {
    animation-direction: reverse;
    animation-range: calc(100% - var(--ob-gradual-blur-size)) 100%;
  }
}
@keyframes ob-gradual-blur-fade-in { from { opacity: 0; } to { opacity: var(--ob-gradual-blur-fade); } }

/* No blur to be had: the user asked for less transparency, or the browser
   can't do backdrop-filter. A plain fade to the page colour does the job. */
@media (prefers-reduced-transparency: reduce) {
  .ob-gradual-blur > * { display: none; }
  .ob-gradual-blur { --ob-gradual-blur-fade: 1; }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .ob-gradual-blur > * { display: none; }
  .ob-gradual-blur { --ob-gradual-blur-fade: 1; }
}
